      {
        "filename": "ci-update-gitops.sh",
        "lang": "bash",
        "code": "#!/bin/bash\nset -euo pipefail\n\nNEW_TAG=\"$1\"\nGITOPS_REPO=\"https://ci-bot:${GIT_TOKEN}@github.com/my-corp/k8s-gitops-manifests.git\"\n\necho \"1. Клонирование GitOps репозитория конфигураций...\"\ngit clone \"$GITOPS_REPO\" /tmp/gitops-repo\ncd /tmp/gitops-repo/apps/auth-service/overlays/dev\n\necho \"2. Обновление тега образа на $NEW_TAG через Kustomize...\"\nkustomize edit set image auth-service=myregistry.io/auth-service:\"$NEW_TAG\"\n\necho \"3. Фиксация изменений и коммит в Git...\"\ngit config user.name \"CI-Automation-Bot\"\ngit config user.email \"bot@company.internal\"\ngit add kustomization.yaml\ngit commit -m \"Auto-deploy: update auth-service image to $NEW_TAG [skip ci]\"\ngit push origin main\n\necho \"✅ GitOps репозиторий успешно обновлен. ArgoCD запустит деплой.\" "
      }
